{"command":"python3 -c "
import re

with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

# Check sections
sections = ['# Overview', '# Input data', '# Methods', '# Generated outputs', '# Main results', '# Limitations', '# Reproducibility']
for s in sections:
    pattern = re.escape(s) + r'\n(.*?)(?=\n#|\Z)'
    match = re.search(pattern, content, re.DOTALL)
    if match:
        text = match.group(1).strip()
        # Count text chars (excluding markdown formatting)
        text_no_md = re.sub(r'[*_`\[\]()#]', '', text)
        text_len = len(text_no_md.strip())
        print(f'{s}: {text_len} chars of text - {\"OK\" if text_len >= 80 else \"TOO SHORT\"} ')
    else:
        print(f'{s}: MISSING')

# Check for API claims
if 'live API' in content.lower() and 'no' not in content.lower().split('live API')[0].split('\n')[-1]:
    print('WARNING: Possible live API claim detected')
else:
    print('No live API claims detected')

# Check output references
for path in ['outputs/t01_selected_indicators.csv', 'outputs/t04_gtfs_summary.json', 'outputs/t10_accessibility_scores.csv', 'outputs/t13_city_clusters.csv', 'outputs/t14_validation_summary.json']:
    if path in content:
        print(f'Reference to {path}: OK')
    else:
        print(f'Reference to {path}: MISSING')
""}
